        def _post_revoke_credential(
            self, tenant: str, credential_id: str
        ) -> None:
            # reason 可省略（请求体亦可整个缺省）；已吊销时任何 reason
            # 均忽略并返回首次结果，非法 reason 仅首次请求 400。
            data = self._read_optional_json()
            # 省略 reason 时传哨兵走默认原因；提供时透传原值，非法
            # reason 的 400 判定由 store 在确认非重复吊销后做出
            # （已吊销时任何 reason 均忽略，含非法值）。
            reason = data["reason"] if "reason" in data else REASON_UNSET
            record = store.revoke_credential(tenant, credential_id, reason)
            self._send_json(
                200,
                {
                    "credential_id": record.credential_id,
                    "status": record.status,
                    "reason": record.reason,
                    "revoked_at": record.revoked_at,
                    "updated_at": record.updated_at,
                },
            )

        def _post_verify_credential(
            self, tenant: str, credential_id: str
        ) -> None:
            # verify 端点的公开错误协议：任何“验签失败”都返回 200 +
            # {"valid": false, "reason": "<非空中文原因>"}，绝不返回
            # 404/500，也不泄露私钥或堆栈。reason 按类别措辞：
            # 请求层（请求*）、资源（凭证不存在）、锚定、签名、密钥。
            try:
                length = int(self.headers.get("Content-Length") or 0)
                raw = self.rfile.read(length) if length > 0 else b""
            except (ValueError, TypeError):
                self._send_invalid("请求体缺失或长度声明非法")
                return
            except Exception:  # noqa: BLE001
                self._send_invalid("请求体读取失败")
                return
            if not raw:
                self._send_invalid("请求体缺失")
                return
            try:
                data = json.loads(raw.decode("utf-8"))
            except UnicodeDecodeError:
                self._send_invalid("请求体不是合法 UTF-8 文本")
                return
            except json.JSONDecodeError:
                self._send_invalid("请求体不是合法 JSON")
                return
            if not isinstance(data, dict):
                self._send_invalid("请求体必须为 JSON 对象")
                return
            if "body" not in data:
                self._send_invalid("请求缺少字段: body")
                return
            if not isinstance(data["body"], dict):
                self._send_invalid("请求字段 body 必须为 JSON 对象")
                return
            if "signature" not in data:
                self._send_invalid("请求缺少字段: signature")
                return
            if not isinstance(data["signature"], str) or not data["signature"]:
                self._send_invalid("请求字段 signature 必须为非空字符串")
                return

            try:
                valid, reason = store.verify_credential(
                    tenant, credential_id, data["body"], data["signature"]
                )
            except Exception:  # noqa: BLE001 验签失败绝不暴露内部细节
                self._send_invalid("验签过程发生内部错误")
                return
            payload: Dict[str, Any] = {"valid": valid}
            if not valid:
                payload["reason"] = reason or "验签失败"
            self._send_json(200, payload)

        def _post_present(self, tenant: str, credential_id: str) -> None:
            # 请求体必须恰为 {"disclose": [...]} 加可选 challenge、
            # expires_in：缺失 disclose、类型非法、重复路径或祖先重叠、
            # 多余字段一律 400；未知凭证 404；空列表表示零披露。
            # challenge 须为非空字符串且按 Unicode 码点不超过 256，
            # 缺省生成 32 位小写 hex；expires_in 须为非布尔整数且
            # 在 1..86400 之间，缺省 300。成功 201 返回演示记录。
            data = self._read_json()
            if "disclose" not in data:
                raise ValidationError("缺少字段: disclose")
            extra = sorted(
                set(data)
                - {"disclose", "challenge", "expires_in", "holder_binding"}
            )
            if extra:
                raise ValidationError(f"多余字段: {', '.join(extra)}")
            challenge = None
            if "challenge" in data:
                challenge = data["challenge"]
                if not isinstance(challenge, str) or not challenge:
                    raise ValidationError("字段 challenge 必须为非空字符串")
                if len(challenge) > 256:
                    raise ValidationError(
                        "字段 challenge 按 Unicode 码点不能超过 256"
                    )
            expires_in = None
            if "expires_in" in data:
                expires_in = data["expires_in"]
                if not isinstance(expires_in, int) or isinstance(
                    expires_in, bool
                ):
                    raise ValidationError("字段 expires_in 必须为整数")
                if not 1 <= expires_in <= 86400:
                    raise ValidationError(
                        "字段 expires_in 须在 1 到 86400 之间"
                    )
            # holder_binding 可选：必须为布尔，缺省 false；为 true 时
            # subject_did 须是本租户已注册 DID（否则由 store 判 400）。
            holder_binding = False
            if "holder_binding" in data:
                holder_binding = data["holder_binding"]
                if not isinstance(holder_binding, bool):
                    raise ValidationError("字段 holder_binding 必须为布尔值")
            record = store.create_presentation(
                tenant,
                credential_id,
                data["disclose"],
                challenge=challenge,
                expires_in=expires_in,
                holder_binding=holder_binding,
            )
            presentation_payload: Dict[str, Any] = {
                "presentation_id": record.presentation_id,
                "credential_id": record.credential_id,
                "issuer_did": record.issuer_did,
                "issuer_key_version": record.issuer_key_version,
                "disclose": record.disclose,
                "claims": record.projection,
                "challenge": record.challenge,
                "expires_at": record.expires_at,
                "proof": record.proof,
            }
            # 仅持有者绑定演示返回 holder_did、holder_key_version、
            # holder_proof；未绑定响应字段集合与旧流程完全一致。
            if record.holder_did is not None:
                presentation_payload["holder_did"] = record.holder_did
                presentation_payload["holder_key_version"] = (
                    record.holder_key_version
                )
                presentation_payload["holder_proof"] = record.holder_proof
            self._send_json(201, presentation_payload)

        def _post_verify_presentation(
            self, tenant: str, presentation_id: str
        ) -> None:
            # 与凭证 verify 相同的公开错误协议：任何“验签失败”都返回
            # 200 + {"valid": false, "reason": "<非空中文原因>"}，绝不
            # 返回 404/500。
            try:
                length = int(self.headers.get("Content-Length") or 0)
                raw = self.rfile.read(length) if length > 0 else b""
            except (ValueError, TypeError):
                self._send_invalid("请求体缺失或长度声明非法")
                return
            except Exception:  # noqa: BLE001
                self._send_invalid("请求体读取失败")
                return
            if not raw:
                self._send_invalid("请求体缺失")
                return
            try:
                data = json.loads(raw.decode("utf-8"))
            except UnicodeDecodeError:
                self._send_invalid("请求体不是合法 UTF-8 文本")
                return
            except json.JSONDecodeError:
                self._send_invalid("请求体不是合法 JSON")
                return
            if not isinstance(data, dict):
                self._send_invalid("请求体必须为 JSON 对象")
                return
            if "presentation" not in data:
                self._send_invalid("请求缺少字段: presentation")
                return
            extra = sorted(set(data) - {"presentation", "challenge"})
            if extra:
                self._send_invalid(f"请求含多余字段: {', '.join(extra)}")
                return
            challenge = CHALLENGE_UNSET
            if "challenge" in data:
                challenge = data["challenge"]
                if not isinstance(challenge, str) or not challenge:
                    self._send_invalid(
                        "请求字段 challenge 必须为非空字符串"
                    )
                    return

            try:
                valid, reason = store.verify_presentation(
                    tenant, presentation_id, data["presentation"], challenge
                )
            except Exception:  # noqa: BLE001 验签失败绝不暴露内部细节
                self._send_invalid("验签过程发生内部错误")
                return
            payload: Dict[str, Any] = {"valid": valid}
            if not valid:
                payload["reason"] = reason or "验签失败"
            self._send_json(200, payload)

        # ------------------------------------------------------------ #
        # 谓词证明
        # ------------------------------------------------------------ #
        def _post_prove(self, tenant: str, credential_id: str) -> None:
            # 请求体必须恰为 {"predicates": [...]} 加可选 challenge、
            # expires_in：缺失/空 predicates、元素字段或 op 非法、路径
            # 重复或祖先重叠、多余字段一律 400；未知凭证 404。
            # challenge 须为非空字符串且按 Unicode 码点不超过 256，
            # 缺省生成 32 位小写 hex；expires_in 须为非布尔整数且
            # 在 1..86400 之间，缺省 300。成功 201 返回证明记录。
            data = self._read_json()
            if "predicates" not in data:
                raise ValidationError("缺少字段: predicates")
            extra = sorted(set(data) - {"predicates", "challenge", "expires_in"})
            if extra:
                raise ValidationError(f"多余字段: {', '.join(extra)}")
            challenge = None
            if "challenge" in data:
                challenge = data["challenge"]
                if not isinstance(challenge, str) or not challenge:
                    raise ValidationError("字段 challenge 必须为非空字符串")
                if len(challenge) > 256:
                    raise ValidationError(
                        "字段 challenge 按 Unicode 码点不能超过 256"
                    )
            expires_in = None
            if "expires_in" in data:
                expires_in = data["expires_in"]
                if not isinstance(expires_in, int) or isinstance(
                    expires_in, bool
                ):
                    raise ValidationError("字段 expires_in 必须为整数")
                if not 1 <= expires_in <= 86400:
                    raise ValidationError(
                        "字段 expires_in 须在 1 到 86400 之间"
                    )
            record = store.create_proof(
                tenant,
                credential_id,
                data["predicates"],
                challenge=challenge,
                expires_in=expires_in,
            )
            self._send_json(
                201,
                {
                    "proof_id": record.proof_id,
                    "credential_id": record.credential_id,
                    "issuer_did": record.issuer_did,
                    "issuer_key_version": record.issuer_key_version,
                    "predicates": record.predicates,
                    "results": record.results,
                    "challenge": record.challenge,
                    "expires_at": record.expires_at,
                    "proof": record.proof,
                },
            )

        def _post_verify_proof(self, tenant: str, proof_id: str) -> None:
            # 与凭证/演示 verify 相同的公开错误协议：任何“验签失败”都
            # 返回 200 + {"valid": false, "reason": "<非空中文原因>"}，
            # 绝不返回 404/500。失败不消费；并发仅一次成功并持久化。
            try:
                length = int(self.headers.get("Content-Length") or 0)
                raw = self.rfile.read(length) if length > 0 else b""
            except (ValueError, TypeError):
                self._send_invalid("请求体缺失或长度声明非法")
                return
            except Exception:  # noqa: BLE001
                self._send_invalid("请求体读取失败")
                return
            if not raw:
                self._send_invalid("请求体缺失")
                return
            try:
                data = json.loads(raw.decode("utf-8"))
            except UnicodeDecodeError:
                self._send_invalid("请求体不是合法 UTF-8 文本")
                return
            except json.JSONDecodeError:
                self._send_invalid("请求体不是合法 JSON")
                return
            if not isinstance(data, dict):
                self._send_invalid("请求体必须为 JSON 对象")
                return
            if "proof" not in data:
                self._send_invalid("请求缺少字段: proof")
                return
            extra = sorted(set(data) - {"proof", "challenge"})
            if extra:
                self._send_invalid(f"请求含多余字段: {', '.join(extra)}")
                return
            challenge = CHALLENGE_UNSET
            if "challenge" in data:
                challenge = data["challenge"]
                if not isinstance(challenge, str) or not challenge:
                    self._send_invalid(
                        "请求字段 challenge 必须为非空字符串"
                    )
                    return

            try:
                valid, reason = store.verify_proof(
                    tenant, proof_id, data["proof"], challenge
                )
            except Exception:  # noqa: BLE001 验签失败绝不暴露内部细节
                self._send_invalid("验签过程发生内部错误")
                return
            payload: Dict[str, Any] = {"valid": valid}
            if not valid:
                payload["reason"] = reason or "验签失败"
            self._send_json(200, payload)

        # ------------------------------------------------------------ #
        # 信任锚点
        # ------------------------------------------------------------ #
        @staticmethod
        def _trust_anchor_payload(record: Any) -> Dict[str, Any]:
            return {
                "did": record.did,
                "public_key": record.public_key,
                "key_version": record.key_version,
                "status": record.status,
                "updated_at": record.updated_at,
            }

        def _post_trust_anchors(self, tenant: str) -> None:
            # 字段依次为：did 非空字符串、public_key 为 P-256 PEM、
            # key_version 为非布尔正整数；多余字段一律 400。
            data = self._read_json()
            self._require_fields(data, ("did", "public_key"))
            if "key_version" not in data:
                raise ValidationError("缺少字段: key_version")
            extra = sorted(
                set(data) - {"did", "public_key", "key_version"}
            )
            if extra:
                raise ValidationError(f"多余字段: {', '.join(extra)}")
            record, created = store.register_trust_anchor(
                tenant,
                data["did"],
                data["public_key"],
                data["key_version"],
            )
            # 新建 201；同 DID/版本同 PEM 幂等重试 200；PEM 不同由
            # store 抛 ConflictError -> 409。
            self._send_json(
                201 if created else 200,
                self._trust_anchor_payload(record),
            )

        def _get_trust_anchors(self, tenant: str, did: str) -> None:
            # 返回该 DID 的全部锚点版本；未知 DID（含他租户）404。
            records = store.list_trust_anchors(tenant, did)
            self._send_json(
                200, [self._trust_anchor_payload(r) for r in records]
            )

        def _get_trust_anchor_history(
            self, tenant: str, did: str, query: str
        ) -> None:
            # GET /v1/trust/anchors/{did}/history?limit=&after=：只读
            # 信任锚点生命周期历史。limit 缺省 50，须为 1..200 的 ASCII
            # 十进制整数；after 缺省 0，须为非负 ASCII 十进制整数；
            # 重复/空白/布尔词/小数/符号/Unicode 数字一律 400。未知或
            # 他租户 DID 404；已有 DID 无历史返回空页，空页 next_after
            # 保持 after。纯只读：不写任何状态、不记审计。
            if not did:
                raise ValidationError("路径缺少 did")
            params = parse_qs(query, keep_blank_values=True)

            limit_values = params.get("limit")
            if limit_values is not None:
                if len(limit_values) != 1:
                    raise ValidationError("查询参数 limit 只能提供一次")
                limit = _parse_nonneg_int(limit_values[0], "limit")
                if not 1 <= limit <= 200:
                    raise ValidationError(
                        "查询参数 limit 须在 1 到 200 之间"
                    )
            else:
                limit = 50

            after_values = params.get("after")
            if after_values is not None:
                if len(after_values) != 1:
                    raise ValidationError("查询参数 after 只能提供一次")
                after = _parse_nonneg_int(after_values[0], "after")
            else:
                after = 0

            events, next_after = store.list_trust_anchor_history(
                tenant, did, after, limit
            )
            self._send_json(
                200,
                {
                    "did": did,
                    "events": [
                        {
                            "key_version": event.key_version,
                            "action": event.action,
                            "status": event.status,
                            "updated_at": event.updated_at,
                            "cursor": event.cursor,
                        }
                        for event in events
                    ],
                    "next_after": next_after,
                },
            )

        def _get_trust_anchor_discovery(self, tenant: str, query: str) -> None:
            # GET /v1/trust/anchors?limit=&after=&status=：跨 DID 只读
            # 发现。查询参数仅允许 limit、after、status：limit 缺省 50、
            # 须为 1..200 的 ASCII 十进制整数；after 缺省 0、须为非负
            # ASCII 十进制整数；status 可省略，提供时只能为 active 或
            # revoked。重复参数、空值、空白、符号、小数、布尔词、Unicode
            # 数字、越界及未知参数一律 400。响应恰含 anchors、next_after；
            # 每项恰含 did、public_key、key_version、status、updated_at、
            # cursor。先按 status 过滤，再按 cursor>after 升序取至多
            # limit；空结果 next_after 等于 after，无锚点也返回 200 空
            # 数组。纯只读：不写任何状态、不记审计。
            params = parse_qs(query, keep_blank_values=True)
            unknown = sorted(set(params) - {"limit", "after", "status"})
            if unknown:
                raise ValidationError(
                    f"不支持的查询参数: {', '.join(unknown)}"
                )

            limit_values = params.get("limit")
            if limit_values is not None:
                if len(limit_values) != 1:
                    raise ValidationError("查询参数 limit 只能提供一次")
                limit = _parse_nonneg_int(limit_values[0], "limit")
                if not 1 <= limit <= 200:
                    raise ValidationError(
                        "查询参数 limit 须在 1 到 200 之间"
                    )
            else:
                limit = 50

            after_values = params.get("after")
            if after_values is not None:
                if len(after_values) != 1:
                    raise ValidationError("查询参数 after 只能提供一次")
                after = _parse_nonneg_int(after_values[0], "after")
            else:
                after = 0

            status_values = params.get("status")
            status: Optional[str] = None
            if status_values is not None:
                if len(status_values) != 1:
                    raise ValidationError("查询参数 status 只能提供一次")
                if status_values[0] not in ("active", "revoked"):
                    raise ValidationError(
                        "查询参数 status 仅支持 active 或 revoked"
                    )
                status = status_values[0]

            anchors, next_after = store.list_trust_anchor_entries(
                tenant, after, limit, status
            )
            self._send_json(
                200,
                {
                    "anchors": [
                        {
                            "did": record.did,
                            "public_key": record.public_key,
                            "key_version": record.key_version,
                            "status": record.status,
                            "updated_at": record.updated_at,
                            "cursor": record.cursor,
                        }
                        for record in anchors
                    ],
                    "next_after": next_after,
                },
            )

        def _put_trust_anchor_status(
            self, tenant: str, did: str, key_version: str
        ) -> None:
            # 请求体必须恰为 {"status": "revoked"}；路径 key_version
            # 须为非布尔正整数（路径参数为字符串）。
            data = self._read_json()
            if "status" not in data:
                raise ValidationError("缺少字段: status")
            extra = sorted(set(data) - {"status"})
            if extra:
                raise ValidationError(f"多余字段: {', '.join(extra)}")
            if data["status"] != "revoked":
                raise ValidationError(
                    f"字段 status 非法: {data['status']!r}（仅支持 revoked）"
                )
            if (
                not key_version
                or any(ch < "0" or ch > "9" for ch in key_version)
                or int(key_version) < 1
            ):
                raise ValidationError("路径参数 key_version 必须为正整数")
            record = store.revoke_trust_anchor(tenant, did, int(key_version))
            # 首次吊销与幂等重试均 200，updated_at 保持首次值
            self._send_json(200, self._trust_anchor_payload(record))

        def _post_trust_anchor_rotate(
            self, tenant: str, did: str
        ) -> None:
            # 请求体必须恰含 from_key_version（非布尔正整数）与
            # public_key（可解析的 P-256 PEM）；缺失、多余、类型或
            # PEM 非法一律 400。DID 不存在（含他租户）由 store 判 404。
            data = self._read_json()
            if "from_key_version" not in data:
                raise ValidationError("缺少字段: from_key_version")
            if "public_key" not in data:
                raise ValidationError("缺少字段: public_key")
            extra = sorted(
                set(data) - {"from_key_version", "public_key"}
            )
            if extra:
                raise ValidationError(f"多余字段: {', '.join(extra)}")
            from_key_version = data["from_key_version"]
            if (
                not isinstance(from_key_version, int)
                or isinstance(from_key_version, bool)
                or from_key_version < 1
            ):
                raise ValidationError(
                    "字段 from_key_version 必须为正整数"
                )
            record, created = store.rotate_trust_anchor(
                tenant, did, from_key_version, data["public_key"]
            )
            # 新建版本 201；同一前置同 PEM 的幂等重试 200。
            self._send_json(
                201 if created else 200,
                self._trust_anchor_payload(record),
            )

        def _post_trust_dids_verify_document(self, tenant: str) -> None:
            # 跨系统 DID 文档验真：公开错误协议，任何失败都返回
            # 200 + {"valid": false, "reason": "<非空中文原因>"}，成功仅
            # {"valid": true}。请求体须恰含 document（JSON 对象）；非法
            # JSON/非对象/缺失/多余字段均为请求类原因。纯只读，不登记
            # 资源、不写历史或审计，跨租户不可探测。
            try:
                length = int(self.headers.get("Content-Length") or 0)
                raw = self.rfile.read(length) if length > 0 else b""
            except (ValueError, TypeError):
                self._send_invalid("请求体缺失或长度声明非法")
                return
            except Exception:  # noqa: BLE001
                self._send_invalid("请求体读取失败")
                return
            if not raw:
                self._send_invalid("请求体缺失")
                return
            try:
                data = json.loads(raw.decode("utf-8"))
            except UnicodeDecodeError:
                self._send_invalid("请求体不是合法 UTF-8 文本")
                return
            except json.JSONDecodeError:
                self._send_invalid("请求体不是合法 JSON")
                return

            try:
                valid, reason = store.verify_trust_did_document(tenant, data)
            except Exception:  # noqa: BLE001 验真失败绝不暴露内部细节
                self._send_invalid("验真过程发生内部错误")
                return
            payload: Dict[str, Any] = {"valid": valid}
            if not valid:
                payload["reason"] = reason or "DID 文档验真失败"
            self._send_json(200, payload)

        def _post_trust_dids_verify_document_batch(self, tenant: str) -> None:
            # 批量跨系统 DID 文档验真：与单项相同的公开错误协议，任何失败
            # 都返回 HTTP 200。请求体须恰为 {"documents": [文档...]}，
            # 数组非空且不超过 100 项；请求体非法（外层缺失、非法 JSON、
            # 非对象、字段缺失或多余、documents 非数组、空数组或超过上限）
            # 时返回 {"results": [], "reason": "请求..."}。请求级合法时
            # 返回 {"results": [...]}，长度与顺序与输入一致，逐项复用单项
            # 验真规则，失败不短路。纯只读，不登记资源，不写状态、历史或
            # 审计，仅使用当前租户锚点。
            try:
                length = int(self.headers.get("Content-Length") or 0)
                raw = self.rfile.read(length) if length > 0 else b""
            except (ValueError, TypeError):
                self._send_json(
                    200,
                    {"results": [],
                     "reason": "请求不合法: 请求体缺失或长度声明非法"},
                )
                return
            except Exception:  # noqa: BLE001
                self._send_json(
                    200, {"results": [], "reason": "请求不合法: 请求体读取失败"}
                )
                return
            if not raw:
                self._send_json(
                    200, {"results": [], "reason": "请求不合法: 请求体缺失"}
                )
                return
            try:
                data = json.loads(raw.decode("utf-8"))
            except UnicodeDecodeError:
                self._send_json(
                    200,
                    {"results": [], "reason": "请求不合法: 请求体不是合法 UTF-8 文本"},
                )
                return
            except json.JSONDecodeError:
                self._send_json(
                    200, {"results": [], "reason": "请求不合法: 请求体不是合法 JSON"}
                )
                return

            try:
                ok, reason, results = store.verify_trust_did_documents_batch(
                    tenant, data
                )
            except Exception:  # noqa: BLE001 验真失败绝不暴露内部细节
                self._send_json(
                    200, {"results": [], "reason": "请求不合法: 验真过程发生内部错误"}
                )
                return
            if not ok:
                self._send_json(
                    200, {"results": [], "reason": reason or "请求不合法"}
                )
                return
            self._send_json(200, {"results": results})

        def _post_trust_verify(self, tenant: str) -> None:

def create_presentation(
    self,
    tenant_id: str,
    credential_id: str,
    disclose: Any,
    challenge: Optional[str] = None,
    expires_in: Optional[int] = None,
    holder_binding: bool = False,
) -> PresentationRecord:
    """对本租户已签发凭证生成选择性披露演示并持久化，记审计。

    - 凭证不存在（含他租户资源）抛 NotFoundError；disclose 非法
      （非数组、路径语法/越界/重复/祖先重叠）抛 ValidationError；
      空列表表示零披露；
    - challenge 缺省时生成 32 位小写 hex；expires_in 缺省 300 秒，
      expires_at 为当前 UTC 时间加 expires_in 秒（Z 结尾秒精度）；
    - challenge 与 expires_at 均写入被签名的演示正文并持久化；
    - proof 为 ES256 签名，覆盖除 proof 外按 key 升序规范化 JSON，
      使用凭证 issuer_key_version（旧凭证缺省按 1）对应的历史私钥；
      issuer proof 的覆盖范围不随持有者绑定改变；
    - holder_binding 为 True 时，凭证 subject_did 必须是本租户已
      注册 DID，否则 ValidationError（400）；额外写入 holder_did
      （即 subject_did）、holder_key_version（持有者当前密钥版本）
      与 holder_proof（持有者当前私钥对“去掉 proof、holder_proof
      后的完整演示对象 + tenant_id”规范化 JSON 的 ES256 签名）。
      未绑定（缺省 False）不注入任何 holder_* 字段，与旧流程完全
      兼容；
    - presentation_id 为 vp_ 加 32 位小写 hex。
    """
    if challenge is None:
        challenge = uuid.uuid4().hex
    if expires_in is None:
        expires_in = DEFAULT_EXPIRES_IN
    expires_at = _utc_after(expires_in)
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        cred = (
            bucket["credentials"].get(credential_id)
            if bucket is not None else None
        )
        if cred is None:
            raise NotFoundError(f"凭证不存在: {credential_id}")
        stored_body = cred["body"]
        claims = stored_body.get("claims", {})
        if not isinstance(claims, dict):
            raise ValidationError("凭证 claims 不是 JSON 对象，无法披露")

        parsed = _validate_disclose(claims, disclose)
        projection = _project_claims(claims, parsed)

        issuer_did = stored_body["issuer_did"]
        version = int(stored_body.get("issuer_key_version", 1))
        # 签发者 DID 已停用：拒绝生成演示，409 且不留任何记录/审计。
        issuer_rec = bucket["dids"].get(issuer_did)
        if self._is_did_deactivated_locked(issuer_rec):
            raise ConflictError(
                f"签发者 DID 已停用，不能生成演示: {issuer_did}"
            )
        private_pem = self._private_key_for_version_locked(
            bucket, issuer_did, version
        )
        if not private_pem:
            raise ValidationError(
                "历史私钥不可用: 签发者 "
                f"{issuer_did} 密钥版本 {version} 的私钥不存在"
            )
        # 签发密钥版本已吊销：拒绝生成，400 且不留任何记录/审计。
        issuer_entry = self._key_history_entry_by_version_locked(
            bucket, issuer_did, version
        )
        if (
            issuer_entry is not None
            and issuer_entry.get("status") == "revoked"
        ):
            raise ValidationError(
                "签发密钥版本已吊销，不能生成演示: "
                f"{issuer_did}#{version}"
            )

        # 持有者绑定：subject_did 须为本租户已注册 DID，使用其当前
        # 密钥版本私钥签名；未绑定不查询、不注入任何 holder_* 字段。
        holder_did: Optional[str] = None
        holder_key_version: Optional[int] = None
        holder_private_pem: Optional[str] = None
        if holder_binding:
            holder_did = stored_body.get("subject_did")
            if not isinstance(holder_did, str) or not holder_did:
                raise ValidationError(
                    "凭证缺少合法 subject_did，无法进行持有者绑定"
                )
            holder_rec = bucket["dids"].get(holder_did)
            if holder_rec is None:
                raise ValidationError(
                    f"subject_did 不是本租户已注册 DID: {holder_did}"
                )
            holder_key_version = int(holder_rec.get("key_version", 1))
            holder_private_pem = self._private_key_for_version_locked(
                bucket, holder_did, holder_key_version
            )
            if not holder_private_pem:
                raise ValidationError(
                    "持有者当前密钥不可用: 持有者 "
                    f"{holder_did} 密钥版本 {holder_key_version} 的私钥不存在"
                )
            # 绑定的持有者密钥版本已吊销：拒绝生成，400 且不留记录。
            holder_entry = self._key_history_entry_by_version_locked(
                bucket, holder_did, holder_key_version
            )
            if (
                holder_entry is not None
                and holder_entry.get("status") == "revoked"
            ):
                raise ValidationError(
                    "持有者密钥版本已吊销，不能生成绑定演示: "
                    f"{holder_did}#{holder_key_version}"
                )

        snapshot = self._snapshot_locked()
        try:
            presentation_id = f"vp_{uuid.uuid4().hex}"
            disclose_paths = [pointer for pointer, _ in parsed]
            unsigned: Dict[str, Any] = {
                "presentation_id": presentation_id,
                "credential_id": credential_id,
                "issuer_did": issuer_did,
                "issuer_key_version": version,
                "disclose": disclose_paths,
                "claims": projection,
                "challenge": challenge,
                "expires_at": expires_at,
            }
            proof = crypto.sign(unsigned, private_pem)
            row = dict(unsigned)
            row["proof"] = proof
            if holder_binding:
                # holder_proof 覆盖去掉 proof、holder_proof 后的完整
                # 演示对象（含 holder_did/holder_key_version）及
                # tenant_id；issuer proof 覆盖范围保持不变。
                holder_payload = dict(unsigned)
                holder_payload["holder_did"] = holder_did
                holder_payload["holder_key_version"] = holder_key_version
                holder_payload["tenant_id"] = tenant_id
                holder_proof = crypto.sign(
                    holder_payload, holder_private_pem
                )
                row["holder_did"] = holder_did
                row["holder_key_version"] = holder_key_version
                row["holder_proof"] = holder_proof
            bucket["presentations"][presentation_id] = row
            self._append_audit_locked(
                tenant_id, AUDIT_PRESENTATION_CREATED,
                "presentation", presentation_id,
            )
            self._save_locked()
            return self._presentation_record(row)
        except Exception:
            self._restore_locked(snapshot)
            raise

def get_presentation(
    self, tenant_id: str, presentation_id: str
) -> PresentationRecord:
    """查询本租户演示记录；不存在（含他租户资源）抛 NotFoundError。"""
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        row = (
            bucket["presentations"].get(presentation_id)
            if bucket is not None else None
        )
        if row is None:
            raise NotFoundError(f"演示不存在: {presentation_id}")
        return self._presentation_record(row)

def verify_presentation(
    self,
    tenant_id: str,
    presentation_id: str,
    presentation: Any,
    challenge: Any = CHALLENGE_UNSET,
) -> Tuple[bool, str]:
    """以存储记录为锚校验选择性披露演示，返回 (是否有效, 失败原因)。

    校验顺序：请求 -> 资源 ID -> 绑定（含 challenge）-> 已消费 ->
    过期（当前时间 >= expires_at）-> 投影 -> proof 格式与签名 ->
    吊销。新演示（存储记录含 challenge）要求请求恰含 presentation
    与 challenge，且请求 challenge、演示 challenge 与 proof 覆盖的
    存储 challenge 三者一致；旧演示（无 challenge）只接受恰含
    presentation 的请求，不做挑战、过期与消费检查。

    验签成功后在消费锁内复查已消费/到期/吊销：复查到期即返回
    “演示已过期”，不消费、不记审计；未到期并发验证仅一次成功，
    成功时原子标记已消费并记一次 presentation.consumed（标记与
    事件同一次原子写，失败回滚不记），跨重启保留；已消费优先于
    过期与吊销；签名成功但已吊销返回“凭证已吊销：<原因>”且
    不消费。任何失败均返回非空中文原因，绝不抛异常、不泄露私钥。
    """
    if not isinstance(presentation, dict):
        return False, "请求不合法: 字段 presentation 必须为 JSON 对象"

    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        row = (
            bucket["presentations"].get(presentation_id)
            if bucket is not None else None
        )
        if row is None:
            return False, f"演示不存在: {presentation_id}"

        # 新/旧演示按存储记录是否含 challenge 判定
        is_replay_protected = "challenge" in row
        # 持有者绑定演示按存储记录是否含 holder_did 判定（绑定演示
        # 一定也是防重放新演示）。
        is_holder_bound = "holder_did" in row
        if is_replay_protected:
            if challenge is CHALLENGE_UNSET:
                return False, "请求缺少字段: challenge"
        elif challenge is not CHALLENGE_UNSET:
            return False, "请求含多余字段: challenge"

        expected_keys = {
            "presentation_id",
            "credential_id",
            "issuer_did",
            "issuer_key_version",
            "disclose",
            "claims",
            "proof",
        }
        if is_replay_protected:
            expected_keys |= {"challenge", "expires_at"}
        if is_holder_bound:
            expected_keys |= {
                "holder_did",
                "holder_key_version",
                "holder_proof",
            }
        if set(presentation) != expected_keys:
            return False, (
                "锚定校验失败: presentation 字段集合与存储记录不一致"
            )
        proof = presentation.get("proof")
        if not isinstance(proof, str) or not proof:
            return False, "请求不合法: 字段 proof 必须为非空字符串"
        if presentation.get("presentation_id") != presentation_id:
            return False, (
                "锚定校验失败: presentation_id 与路径或存储记录不一致"
            )
        if presentation.get("credential_id") != row.get("credential_id"):
            return False, (
                "锚定校验失败: credential_id 与存储记录不一致"
            )
        if presentation.get("issuer_did") != row.get("issuer_did"):
            return False, "锚定校验失败: issuer_did 与存储记录不一致"
        stored_version = int(row.get("issuer_key_version", 1))
        version_obj = presentation.get("issuer_key_version")
        if (
            not isinstance(version_obj, int)
            or isinstance(version_obj, bool)
            or version_obj != stored_version
        ):
            return False, (
                "锚定校验失败: issuer_key_version 与存储记录不一致"
            )
        if presentation.get("disclose") != list(row.get("disclose", [])):
            return False, "锚定校验失败: disclose 与存储记录不一致"

        if is_holder_bound:
            # holder 字段与存储记录逐一锚定；holder_proof 还须为
            # 非空字符串（holder_did 必须等于凭证 subject_did 的
            # 进一步绑定在生成时已保证，此处再与存储行核对）。
            if presentation.get("holder_did") != row.get("holder_did"):
                return False, (
                    "锚定校验失败: holder_did 与存储记录不一致"
                )
            stored_holder_version = row.get("holder_key_version")
            holder_version_obj = presentation.get("holder_key_version")
            if (
                not isinstance(holder_version_obj, int)
                or isinstance(holder_version_obj, bool)
                or holder_version_obj != stored_holder_version
            ):
                return False, (
                    "锚定校验失败: holder_key_version 与存储记录不一致"
                )
            holder_proof = presentation.get("holder_proof")
            if not isinstance(holder_proof, str) or not holder_proof:
                return False, (
                    "请求不合法: 字段 holder_proof 必须为非空字符串"
                )

        if is_replay_protected:
            # 请求 challenge、演示 challenge 与 proof 覆盖的存储
            # challenge 三者必须一致
            stored_challenge = row.get("challenge")
            if presentation.get("challenge") != stored_challenge:
                return False, (
                    "锚定校验失败: challenge 与存储记录不一致"
                )
            if challenge != stored_challenge:
                return False, (
                    "锚定校验失败: 请求 challenge 与存储记录不一致"
                )
            if presentation.get("expires_at") != row.get("expires_at"):
                return False, (
                    "锚定校验失败: expires_at 与存储记录不一致"
                )
            # 已消费优先于过期与吊销
            if row.get("consumed"):
                return False, "演示已消费"
            try:
                expires_at = _parse_utc_z(row["expires_at"])
            except (KeyError, TypeError, ValueError):
                return False, "验签过程发生内部错误"
            if datetime.now(timezone.utc) >= expires_at:
                return False, "演示已过期"

        obj_claims = presentation.get("claims")
        if not isinstance(obj_claims, dict):
            return False, "请求不合法: 演示 claims 必须为 JSON 对象"

        credential_id = row["credential_id"]
        issuer_did = row["issuer_did"]
        cred = bucket["credentials"].get(credential_id)
        if cred is None:
            return False, f"凭证不存在: {credential_id}"
        source_claims = cred["body"].get("claims", {})
        credential_status = cred.get("status")
        revoke_reason = cred.get("revoke_reason")
        credential_expires_at = cred["body"].get("expires_at")

            return entry.get("private_key_pem")
    return None

@staticmethod
def _presentation_record(row: Dict[str, Any]) -> PresentationRecord:
    return PresentationRecord(
        presentation_id=row["presentation_id"],
        credential_id=row["credential_id"],
        issuer_did=row["issuer_did"],
        issuer_key_version=int(row["issuer_key_version"]),
        disclose=list(row.get("disclose", [])),
        projection=row.get("claims", {}),
        proof=row["proof"],
        challenge=row.get("challenge"),
        expires_at=row.get("expires_at"),
        holder_did=row.get("holder_did"),
        holder_key_version=(
            int(row["holder_key_version"])
            if row.get("holder_key_version") is not None
            else None
        ),
        holder_proof=row.get("holder_proof"),
    )

